function levDist(a,b){
  var m=a.length,n=b.length;
  if(!m) return n; if(!n) return m;
  var prev=[],cur=[];
  for(var j=0;j<=n;j++) prev[j]=j;
  for(var i=1;i<=m;i++){
    cur[0]=i;
    for(var k=1;k<=n;k++){
      cur[k]=Math.min(prev[k]+1, cur[k-1]+1, prev[k-1]+(a[i-1]===b[k-1]?0:1));
    }
    var tmp=prev; prev=cur; cur=tmp;
  }
  return prev[n];
}

function fuzzyThreshold(w){ return w.length<5 ? 1 : 2; }

/* Returns 2 for exact/substring match, 1 for fuzzy match, 0 for no match */
function matchWordInTokens(qw, tokens){
  var i, t;
  for(i=0;i<tokens.length;i++){
    t=tokens[i];
    if(t.indexOf(qw)!==-1 || (qw.length>3 && qw.indexOf(t)!==-1 && t.length>3)) return 2;
  }
  if(qw.length>=4){
    var thr=fuzzyThreshold(qw);
    for(i=0;i<tokens.length;i++){
      t=tokens[i];
      if(t[0]!==qw[0]) continue;              /* first-letter gate kills most false positives */
      if(Math.abs(t.length-qw.length)>thr) continue;
      if(levDist(qw,t)<=thr) return 1;
    }
  }
  return 0;
}

var STOPWORDS = {the:1,and:1,for:1,are:1,with:1,from:1,that:1,this:1,have:1,has:1,were:1,will:1,there:1,
  con:1,por:1,para:1,que:1,del:1,las:1,los:1,una:1,uno:1,como:1,esta:1,este:1,hay:1,tengo:1,tiene:1};
function expandQuery(query){
  var q=normStr(query), out=[], seen={};
  function add(w){ if(w && w.length>=3 && !seen[w] && !STOPWORDS[w]){ seen[w]=1; out.push(w); } }
  var pq;
  for(pq in SEARCH_PHRASES){
    if(q.indexOf(pq)!==-1){
      SEARCH_PHRASES[pq].forEach(add);
    }
  }
  q.split(/\s+/).forEach(function(w){
    if(w==="va"){ add("veteran"); add("veterans"); }
    add(w);
    var syn=SEARCH_SYNONYMS[w];
    if(!syn && w.length>=4){
      /* typo-tolerant: fuzzy-match the word against synonym keys ("docter"->"doctor") */
      var best=null, bd=99, k2, d;
      for(k2 in SEARCH_SYNONYMS){
        if(k2[0]!==w[0] || Math.abs(k2.length-w.length)>2) continue;
        d=levDist(w,k2);
        if(d<bd){ bd=d; best=k2; }
      }
      if(best && bd<=fuzzyThreshold(w)) syn=SEARCH_SYNONYMS[best];
    }
    if(syn) syn.forEach(add);
  });
  return out;
}

function resourceBlob(r){
  return normStr(r.name+" "+r.org+" "+r.what+" "+r.domain+" "+r.elig);
}

/* Score a resource against a query; 0 = no match */
/* IDF: rare query words (tutoring, eviction) count more than common ones (help, new).
   Built lazily once from the dataset; query words unseen as tokens get max weight. */
var _idfMap = null;
function idf(w){
  if(!_idfMap){
    _idfMap = {};
    var N = DATA.length;
    DATA.forEach(function(r){
      var seen = {};
      resourceBlob(r).split(/\s+/).forEach(function(t){ seen[t]=1; });
      for(var t in seen){ _idfMap[t] = (_idfMap[t]||0)+1; }
    });
    _idfMap._N = N;
  }
  var df = _idfMap[w] || 0;
  return 1 + Math.log(_idfMap._N / (1+df));
}
function scoreResource(r, query){
  var words=expandQuery(query);
  if(!words.length) return 0;
  var tokens=resourceBlob(r).split(/\s+/), score=0;
  words.forEach(function(w){ score+=matchWordInTokens(w,tokens)*idf(w); });
  return score;
}

