function escAttr(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;'); }
function safeUrl(u){
  if(!u) return null;
  var s = String(u).trim();
  return /^(https?:\/\/|tel:|mailto:)/i.test(s) ? s : null;
}
function actionRow(r){
  const phone = extractPhone(r.contact);
  const acts = [];
  if(phone) acts.push(`<a class="act-call" href="${escAttr(phone.href)}" aria-label="${escAttr(t('actCall')+': '+r.name+', '+phone.display)}">📞 ${t('actCall')} ${phone.display}</a>`);
  const web = safeUrl(r.url);
  if(web) acts.push(`<a class="act-web" href="${escAttr(web)}" target="_blank" rel="noopener">🌐 ${t('actWeb')}</a>`);
  if(r.lat && r.lng) acts.push(`<a class="act-dir" href="https://www.google.com/maps/search/?api=1&query=${r.lat},${r.lng}" target="_blank" rel="noopener">📍 ${t('actDir')}</a>`);
  acts.push(`<button class="act-save" onclick="toggleFave(${r.id},this)">${faveBtnInner(r.id)}</button>`);
  acts.push(`<button class="act-share" onclick="shareResource(${r.id})">📤 ${t('shareBtn')}</button>`);
  if(!acts.length) return '';
  return `<div class="card-actions">${acts.join('')}</div>`;
}

function detailActions(r){
  const row = actionRow(r);
  if(!row) return '';
  return row.replace('card-actions', 'card-actions detail-actions');
}

function buildCardList(items){
  if(items.length===0){
    const e = document.createElement('div'); e.className='empty'; e.textContent=t('noMatch');
    return e;
  }
  const wrap = document.createElement('div'); wrap.className='card-list';
  items.forEach(r=>{
    const c = document.createElement('div'); c.className='rcard ' + CAT_CLASS[r.bucket];
    c.innerHTML = `<div class="body">
        <span class="rname" role="link" tabindex="0">${r.name}</span>
        <span class="rorg">${r.org}</span>
        <div class="rmeta">${badgesFor(r)}</div>${actionRow(r)}</div>`;
    const go = ()=>navigate('#/resource/'+r.id);
    const nameEl = c.querySelector('.rname');
    nameEl.addEventListener('click', go);
    nameEl.addEventListener('keydown', (e)=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); go(); } });
    wrap.appendChild(c);
  });
  return wrap;
}

function buildRelatedCardList(wrapped){
  const wrap = document.createElement('div'); wrap.className='card-list';
  wrapped.forEach(({item:r, curated})=>{
    const c = document.createElement('div'); c.className='rcard ' + CAT_CLASS[r.bucket];
    c.innerHTML = `<div class="body">
        <span class="rname" role="link" tabindex="0">${r.name}</span>
        <span class="rorg">${r.org}</span>
        <div class="rmeta">
          ${curated?`<span class="badge curated">${t('directlyConnected')}</span>`:''}
          ${badgesFor(r)}
        </div></div>`;
    const go = ()=>navigate('#/resource/'+r.id);
    const nameEl = c.querySelector('.rname');
    nameEl.addEventListener('click', go);
    nameEl.addEventListener('keydown', (e)=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); go(); } });
    wrap.appendChild(c);
  });
  return wrap;
}

function parseEligibility(text){
  if(!text) return [];
  let parts;
  if(text.includes(';')){
    parts = text.split(';');
  } else {
    const commaCount = (text.match(/,/g)||[]).length;
    parts = commaCount >= 2 ? text.split(',') : [text];
  }
  return parts.map(p=>p.trim().replace(/^(and|or)\s+/i,'').replace(/\.$/,'')).filter(p=>p.length>2);
}


